const params = $('Parâmetros').first().json;
let tasks = $input.all().map(i => i.json);

// Filtro por status pós-busca
if (params.status && params.status !== 'all') {
  tasks = tasks.filter(t => t.status === params.status);
}
// Filtro por categoria
if (params.category) {
  tasks = tasks.filter(t => t.category && t.category.toLowerCase() === params.category.toLowerCase());
}

const categories_found = [...new Set(tasks.map(t => t.category).filter(Boolean))];
const suggested_category = categories_found.length > 0 ? categories_found[0] : null;

const list = tasks.map(t => {
  const icon  = t.status === 'done' ? '✅' : '⏳';
  const hora  = t.scheduled_time ? t.scheduled_time.substring(0,5) : '';
  const score = t.similarity_score ? ` [${(t.similarity_score*100).toFixed(0)}%]` : '';
  return `${icon} [ID:${t.id}] ${t.title} — ${t.category || ''}${hora ? ' '+hora : ''}${score}`;
}).join('\n');

return [{ json: {
  query: params.query,
  total_found: tasks.length,
  tasks,
  list_formatted: list || 'Nenhuma atividade encontrada.',
  categories_found,
  suggested_category
}}];
